-- Seed: 50 internal content pillars + 5,000 internal blog titles.
-- Idempotent: re-running updates metadata and leaves title status untouched.
-- Account to seed. Override with: psql -v acct=N
\if :{?acct}
\else
\set acct 20
\endif
BEGIN;

-- The two permitted authors. Sandeep already exists; Tarkaraj is created once
-- because author rotation requires both. No other author is ever created.
UPDATE blog_authors SET bio = COALESCE(NULLIF(bio,''), 'Digital marketing practitioner writing on multi-channel campaign strategy.'),
       social_links = COALESCE(social_links,'{}'::jsonb) || '{"website":"https://sandeepkumarchaudhary.com/"}'::jsonb
 WHERE id = 1;
SELECT :acct, 'Tarkaraj Jaisi', 'tarkaraj-jaisi',
       'Digital marketing practitioner writing on search, content and messaging channels.',
       ARRAY['SEO','Content Marketing','Messaging Channels']::TEXT[],
       '{"website":"https://tarkarajjaishi.com.np/"}'::jsonb, TRUE
WHERE NOT EXISTS (SELECT 1 FROM blog_authors WHERE slug = 'tarkaraj-jaisi');

-- Runtime defaults: 30-minute interval, disabled until an admin starts it.
SELECT :acct, FALSE, 30,
       ARRAY[(SELECT id FROM blog_authors WHERE slug='sandeep-kumar-chaudhary' ORDER BY id LIMIT 1),
             (SELECT id FROM blog_authors WHERE slug='tarkaraj-jaisi' ORDER BY id LIMIT 1)]::INTEGER[],
       'https://nepalfillings.com'
WHERE NOT EXISTS (SELECT 1 FROM blog_title_bank_settings WHERE account_id = :acct);

-- Always re-resolve the rotation to the two permitted authors, so a settings row
-- created before an author existed repairs itself instead of holding a NULL.
UPDATE blog_title_bank_settings SET author_ids = ARRAY[
    (SELECT id FROM blog_authors WHERE slug='sandeep-kumar-chaudhary' ORDER BY id LIMIT 1),
    (SELECT id FROM blog_authors WHERE slug='tarkaraj-jaisi'          ORDER BY id LIMIT 1)]::INTEGER[],
  updated_at = NOW()
 WHERE account_id = :acct
   AND (SELECT id FROM blog_authors WHERE slug='sandeep-kumar-chaudhary' ORDER BY id LIMIT 1) IS NOT NULL
   AND (SELECT id FROM blog_authors WHERE slug='tarkaraj-jaisi'          ORDER BY id LIMIT 1) IS NOT NULL;

